import random
random.seed(1)
SALTS = 4                                    # one hot key becomes 4 sub-keys
store = {}                                   # shard-level counters: "key#salt" -> count

def incr(key):
    sub = key + "#" + str(random.randrange(SALTS))   # write picks a random suffix
    store[sub] = store.get(sub, 0) + 1

def total(key):
    # a read must add up every sub-key (cost: SALTS reads instead of 1)
    return sum(store.get(key + "#" + str(i), 0) for i in range(SALTS))

for _ in range(1000):
    incr("celebrity")
for sub in sorted(store):
    print(sub, store[sub])                   # load is spread over sub-keys
print("total reads needed:", SALTS)
print("celebrity total =", total("celebrity"))

# Saga: debit A, credit B; if credit fails, compensate by refunding A.
accounts = {"A": 100, "B": 50}
done = set()                                  # idempotency: transfer ids already applied

def debit(tid, acc, amt):
    if (tid, "debit") in done:
        return                                # retry-safe: second call is a no-op
    accounts[acc] -= amt
    done.add((tid, "debit"))

def credit(tid, acc, amt, fail=False):
    if fail:
        raise RuntimeError("shard B down")
    accounts[acc] += amt

def transfer(tid, src, dst, amt, fail_credit=False):
    debit(tid, src, amt)                      # local transaction 1
    try:
        credit(tid, dst, amt, fail_credit)    # local transaction 2
        print(tid, "committed")
    except RuntimeError as e:
        accounts[src] += amt                  # compensating action
        print(tid, "compensated:", e)

print("start:", accounts)
transfer("t1", "A", "B", 30)
print("after t1:", accounts)
transfer("t2", "A", "B", 20, fail_credit=True)
print("after t2:", accounts)
